{
  "project": "whitehorse-copper-belt-skarn-geology-example",
  "aoi_wgs84": [
    -135.5,
    60.3,
    -134.5,
    61.0
  ],
  "grid": {
    "crs": "EPSG:3578",
    "cell_size": 2000,
    "from_aoi": true,
    "x_column": "x_m",
    "y_column": "y_m"
  },
  "budget": {
    "delay": 1.0,
    "max_requests": 40
  },
  "sources": {
    "yk_bedrock": {
      "type": "esri_query",
      "url": "https://mapservices.gov.yk.ca/arcgis/rest/services/GeoYukon/GY_Geological/MapServer/113",
      "where": "1=1",
      "out_fields": "OBJECTID,UNIT_250K,ROCK_CLASS,ROCK_SUBCL,ROCK_MAJOR,SHORT_DESC",
      "licence": {
        "name": "Open Government Licence - Yukon",
        "url": "https://open.yukon.ca/open-government-licence-yukon",
        "verified": false,
        "checked_on": "2026-09-28",
        "check_scope": "licence named in the GEO.ca dataset record for this layer; not re-checked for any later task"
      },
      "record": {
        "catalogue": "GEO.ca geocore",
        "id": "0bd92f7f-923e-414f-8443-65a92f047c47",
        "layer": "GY_Geological/113 Bedrock Geology"
      }
    },
    "yk_faults": {
      "type": "esri_query",
      "url": "https://mapservices.gov.yk.ca/arcgis/rest/services/GeoYukon/GY_Geological/MapServer/114",
      "where": "1=1",
      "out_fields": "OBJECTID,FEATURE,TYPE,CONFIDENCE",
      "licence": {
        "name": "Open Government Licence - Yukon",
        "url": "https://open.yukon.ca/open-government-licence-yukon",
        "verified": false,
        "checked_on": "2026-09-28",
        "check_scope": "licence named in the GEO.ca dataset record for this layer; not re-checked for any later task"
      },
      "record": {
        "catalogue": "GEO.ca geocore",
        "id": "0168e681-61f1-4a7d-8a3c-a076a093605b",
        "layer": "GY_Geological/114 Faults"
      }
    },
    "yk_minfile": {
      "type": "esri_query",
      "url": "https://mapservices.gov.yk.ca/arcgis/rest/services/GeoYukon/GY_Geological/MapServer/4",
      "where": "1=1",
      "out_fields": "OBJECTID,MINFILE_NUMBER,MINFILE_NAME,DEPOSIT_TYPE,DEPOSIT_STATUS,MAIN_COMMODITY",
      "licence": {
        "name": "Open Government Licence - Yukon",
        "url": "https://open.yukon.ca/open-government-licence-yukon",
        "verified": false,
        "checked_on": "2026-09-28",
        "check_scope": "licence named in the GEO.ca dataset record for this layer; not re-checked for any later task"
      },
      "record": {
        "catalogue": "GEO.ca geocore",
        "id": "7f095b49-10b6-4f12-96d7-59bcc9a9c070",
        "layer": "GY_Geological/4 Mineral Occurrences - 250k"
      }
    }
  },
  "features": [
    {
      "name": "plutonic_fraction",
      "type": "polygon_fraction",
      "source": "yk_bedrock",
      "property": "ROCK_CLASS",
      "predicate": {
        "property": "ROCK_CLASS",
        "equals": "plutonic"
      },
      "unit": "fraction",
      "role": "value",
      "definition": "Union area fraction of layer-113 bedrock polygons whose ROCK_CLASS is plutonic."
    },
    {
      "name": "carbonate_bearing_fraction",
      "type": "polygon_fraction",
      "source": "yk_bedrock",
      "property": "ROCK_SUBCL",
      "predicate": {
        "property": "ROCK_SUBCL",
        "regex": "carbonate"
      },
      "unit": "fraction",
      "role": "value",
      "definition": "Union area fraction of layer-113 polygons whose ROCK_SUBCL names carbonate (carbonate or clastic/carbonate)."
    },
    {
      "name": "distance_plutonic_m",
      "type": "distance",
      "source": "yk_bedrock",
      "predicate": {
        "property": "ROCK_CLASS",
        "equals": "plutonic"
      },
      "unit": "m",
      "role": "value",
      "definition": "Distance from cell centre to the nearest plutonic polygon; zero inside plutonic rock."
    },
    {
      "name": "fault_line_density_km_km2",
      "type": "line_density",
      "source": "yk_faults",
      "unit": "km/km2",
      "role": "value",
      "definition": "Sum of in-cell mapped fault length per square kilometre (all fault types and confidence levels)."
    },
    {
      "name": "distance_fault_m",
      "type": "distance",
      "source": "yk_faults",
      "unit": "m",
      "role": "value",
      "definition": "Distance from cell centre to the nearest mapped fault line."
    },
    {
      "name": "skarn_cu_record",
      "type": "point_presence",
      "source": "yk_minfile",
      "predicate": {
        "property": "DEPOSIT_TYPE",
        "equals": "Skarn Cu"
      },
      "buffer": 0,
      "definition": "1 where at least one Yukon MINFILE occurrence with DEPOSIT_TYPE 'Skarn Cu' falls in the cell; 0 means no such record in this extract, not verified absence."
    }
  ],
  "output": {
    "name": "whitehorse_geology_2km",
    "handoff": "aoi_centre"
  },
  "notes": [
    "Example only. It shows the runner's recipe format with one service; it is not a recommended data set for any purpose.",
    "Checks recorded here are from 2026-09-28. Do not treat them as current: confirm host approval, layer ids, fields, licence and service limits for the current task, then set licence.verified only after that check.",
    "The recorded robots.txt observation for mapservices.gov.yk.ca is a service fact, not user approval. Only an approval recorded for the current user, task scope and requested paths may be reused.",
    "This example covers lithology, faults and occurrence records only. Yukon geophysics grids may be behind a browser challenge; do not circumvent access controls. Review any user-provided local grid's source, licence and hash before use."
  ],
  "checked": {
    "on": "2026-09-28",
    "scope": "layer ids, field names and feature counts for this AOI were read from the service on this date; licence from the dataset records",
    "inherits_to_new_tasks": false
  }
}
